// Only active, sampled bone layers allocate output. Programs/bindings stay shared.
import {blendSequenceNumber} from './sequence-blending.js';
export function mixSequencePoseEntries(entries){const total=entries.reduce((n,e)=>n+(e.owner.weight??1),0);return {bone:entries[0].value.bone,layers:entries.map(e=>({...e.value,weight:(e.owner.weight??1)/total}))};}
export function blendSequencePoses(rows){const total=rows.reduce((n,r)=>n+r.weight,0),out={position:[...rows[0].pose.position],scale:[...rows[0].pose.scale],quaternion:[0,0,0,0]},reference=rows.reduce((a,b)=>b.weight>a.weight?b:a).pose.quaternion;let sum=0;for(const{pose,weight}of rows){const w=weight/total,next=sum+weight,t=next?weight/next:0;for(let k=0;k<3;k++){out.position[k]=blendSequenceNumber(out.position[k],pose.position[k],t);out.scale[k]=blendSequenceNumber(out.scale[k],pose.scale[k],t);}sum=next;const sign=pose.quaternion.reduce((n,v,k)=>n+v*reference[k],0)<0?-1:1;for(let k=0;k<4;k++)out.quaternion[k]+=pose.quaternion[k]*w*sign;}const length=Math.hypot(...out.quaternion);for(let k=0;k<4;k++)out.quaternion[k]/=length;return out;}
